#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2.Sprites;

namespace MVZ2.Resources
{
    public class ResourceResolverTags<TKey, TResource> : ResourceResolver<TKey, TResource>
    {
        protected List<string[]> GetTagCandidates(ResourceContext context)
        {
            var list = new List<string[]>();
            if (!string.IsNullOrEmpty(context.languageCode) && context.censored)
            {
                list.Add(new string[] { SpriteHelper.SPRITE_TAG_CENSORED, SpriteHelper.GetLanguageSpriteTag(context.languageCode) });
            }
            if (!string.IsNullOrEmpty(context.languageCode))
            {
                list.Add(new string[] { SpriteHelper.GetLanguageSpriteTag(context.languageCode) });
            }
            if (context.censored)
            {
                list.Add(new string[] { SpriteHelper.SPRITE_TAG_CENSORED });
            }

            list.Add(Array.Empty<string>());

            return list;
        }
    }
}
